  "risks": [
    {
      "risk": "A read-modify-write click update can lose increments when follow requests run concurrently.",
      "mitigation": "Use a database-level atomic increment query or optimistic locking with retry, and execute the increment within the follow transaction before returning the redirect."
    },
    {
      "risk": "Generated codes could collide or contain characters that are unsafe in URL paths.",
      "mitigation": "Use SecureRandom with a fixed URL-safe alphabet, enforce length seven, place a unique constraint on the entity, and retry after collisions."
    },
    {
      "risk": "Broad redirect path handling could intercept API routes or produce incorrect short URLs behind a context path.",
      "mitigation": "Use explicit controller mappings and construct short URLs from the incoming request's scheme, host, port, and context path while preserving the API mappings."
    },
    {
      "risk": "URI parsing alone may accept non-web or malformed authority forms.",
      "mitigation": "Require an absolute URI, exact http/https scheme, and a non-null host; return a consistent JSON 400 response through centralized exception handling."
    },
