    }
  ],
  "decisions": [
    {
      "title": "Use seven-character SecureRandom codes",
      "rationale": "The requirement calls for short, URL-safe, hard-to-guess codes and explicitly requires cryptographically strong randomness.",
      "alternatives": [
        "Sequential numeric codes were rejected because they are easy to enumerate.",
        "UUIDs were rejected because they are much longer than required.",
        "Hashing the original URL was rejected because it can reveal a predictable relationship between URLs and codes."
      ]
    },
    {
      "title": "Use a database unique constraint plus bounded retry",
      "rationale": "The constraint is authoritative under concurrent creation, while retry makes rare random collisions transparent to clients.",
      "alternatives": [
        "An existence check without a constraint was rejected because two concurrent requests can pass the check.",
        "An unbounded retry loop was rejected because it can hang during database or configuration failures."
      ]
    },
    {
      "title": "Use an atomic JPA update for clicks",
      "rationale": "A database expression increment preserves every concurrent follow without lost updates.",
      "alternatives": [
        "Loading the entity, incrementing in Java, and saving was rejected because concurrent transactions can overwrite each other.",
        "A Java synchronized lock was rejected because it would not protect updates across service threads or future instances."
      ]
    },
    {
      "title": "Create a new link for every successful submission",
      "rationale": "Repeated submissions are explicitly allowed to return a new code, and separate records preserve independent click counts.",
      "alternatives": [
        "Deduplicating by original URL was rejected because it would prevent distinct records and codes for repeated submissions."
      ]
    },
    {
      "title": "Return HTTP 302 for follows",
      "rationale": "The specified redirect behavior uses HTTP 302 Found and requires the original URL in Location.",
      "alternatives": [
        "301 was rejected because it implies permanent caching semantics.",
        "307 was rejected because the requested contract specifies 302."
      ]
    },
    {
      "title": "Derive shortUrl from the incoming request",
      "rationale": "This satisfies the stated assumption without requiring deployment-specific configuration or external infrastructure.",
      "alternatives": [
        "A fixed configured public URL was rejected because no such configuration is required and it can be incorrect across environments.",
        "Blindly trusting forwarded headers was rejected because it can produce attacker-controlled URLs unless proxy trust is explicitly configured."
      ]
    },
    {
      "title": "Use RFC 7807 ProblemDetail for all HTTP errors",
      "rationale": "The service must provide stable JSON errors with clear human-readable messages, and Spring's ProblemDetail is the standard implementation available in the selected stack.",
      "alternatives": [
        "Ad hoc error maps were rejected because their fields and content types are less standardized.",
        "HTML error pages were rejected because API clients require JSON."
      ]
    },
    {
      "title": "Match redirect paths to seven-character URL-safe codes",
      "rationale": "The constrained mapping prevents the public redirect controller from intercepting `/api/links/...` routes while reflecting the generated-code format.",
      "alternatives": [
        "A broad `/{code}` mapping was rejected because it can create routing ambiguity with API endpoints.",
        "A catch-all redirect mapping was rejected because unrelated application paths could be treated as codes."
      ]
    }
  ]
}

