    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "original_url", nullable = false, length = 4096)
    private String url;

    @Column(nullable = false, unique = true, length = 7)
    private String code;

    @Column(name = "click_count", nullable = false)
