"},{"path":"src/main/java/com/example/shortener/UrlValidator.java","content":"package com.example.shortener;

import org.springframework.stereotype.Component;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.Locale;

@Component
public class UrlValidator {

    public void validate(String value) {
        if (value == null || value.isBlank()) {
            throw new InvalidUrlException("url is required and must not be blank");
        }

        try {
            URI uri = new URI(value);
            String scheme = uri.getScheme();
            if (!uri.isAbsolute() || scheme == null
                    || !("http".equals(scheme.toLowerCase(Locale.ROOT)
                    || "https".equals(scheme.toLowerCase(Locale.ROOT)))
                    || uri.getHost() == null) {
                throw new InvalidUrlException("url must be an absolute HTTP or HTTPS URL with a valid host");
            }
        } catch (URISyntaxException exception) {
            throw new InvalidUrlException("url must be a valid absolute HTTP or HTTPS URL");
        }
    }
}
"},{"path":"src/main/java/com/example/shortener/LinkService.java","content":"package com.example.shortener;

import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class LinkService {

    private static final int MAX_CREATE_ATTEMPTS = 10;

    private final LinkRepository repository;
    private final ShortCodeGenerator codeGenerator;
    private final UrlValidator urlValidator;

    public LinkService(LinkRepository repository, ShortCodeGenerator codeGenerator, UrlValidator urlValidator) {
        this.repository = repository;
        this.codeGenerator = codeGenerator;
        this.urlValidator = urlValidator;
    }

    public Link create(String url) {
        urlValidator.validate(url);

        for (int attempt = 0; attempt < MAX_CREATE_ATTEMPTS; attempt++) {
            String code = codeGenerator.generate();
            if (repository.existsByCode(code)) {
                continue;
            }

            try {
                return repository.saveAndFlush(new Link(url, code));
            } catch (DataIntegrityViolationException exception) {
                // A concurrent insert may have won the unique-code race. Try again.
            }
        }

        throw new CodeGenerationException();
    }

    @Transactional(readOnly = true)
    public Link findByCode(String code) {
        return repository.findByCode(code)
                .orElseThrow(() -> new LinkNotFoundException(code));
    }

    @Transactional
    public String follow(String code) {
        Link link = repository.findByCode(code)
                .orElseThrow(() -> new LinkNotFoundException(code));
        repository.incrementClickCountByCode(code);
        return link.getUrl();
    }
}
"},{"path":"src/main/java/com/example/shortener/LinkController.java","content":"package com.example.shortener;

import jakarta.validation.Valid;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/links")
public class LinkController {

    private final LinkService linkService;

    public LinkController(LinkService linkService) {
        this.linkService = linkService;
    }

    @PostMapping
    public ResponseEntity<LinkResponse> create(@Valid @RequestBody LinkCreateRequest request,
                                                HttpServletRequest httpRequest) {
        Link link = linkService.create(request.url());
        return ResponseEntity.status(HttpStatus.CREATED)
                .body(toResponse(link, httpRequest));
    }

    @GetMapping("/{code}")
    public LinkResponse details(@PathVariable String code, HttpServletRequest httpRequest) {
        return toResponse(linkService.findByCode(code), httpRequest);
    }

    static LinkResponse toResponse(Link link, HttpServletRequest request) {
        return new LinkResponse(
                link.getUrl(),
                link.getCode(),
                shortUrl(request, link.getCode()),
                link.getClickCount());
    }

    static String shortUrl(HttpServletRequest request, String code) {
        StringBuilder result = new StringBuilder()
                .append(request.getScheme())
                .append("://");
        String host = request.getServerName();
        if (host != null && host.contains(":") && !host.startsWith("[")) {
            result.append('[').append(host).append(']');
        } else {
            result.append(host);
        }

        int port = request.getServerPort();
        boolean defaultPort = ("http".equalsIgnoreCase(request.getScheme()) && port == 80)
                || ("https".equalsIgnoreCase(request.getScheme()) && port == 443);
        if (port > 0 && !defaultPort) {
            result.append(':').append(port);
        }

        String contextPath = request.getContextPath();
        if (contextPath != null && !contextPath.isEmpty() && !"/".equals(contextPath)) {
            result.append(contextPath);
        }
        return result.append('/').append(code).toString();
    }
}
"},{"path":"src/main/java/com/example/shortener/RedirectController.java","content":"package com.example.shortener;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

import java.net.URI;

@RestController
public class RedirectController {

    private final LinkService linkService;

    public RedirectController(LinkService linkService) {
        this.linkService = linkService;
    }

    @GetMapping("/{code:[A-Za-z0-9_-]{7}}")
    public ResponseEntity<Void> redirect(@PathVariable String code) {
        String url = linkService.follow(code);
        return ResponseEntity.status(302).location(URI.create(url)).build();
    }
}
"},{"path":"src/main/java/com/example/shortener/GlobalExceptionHandler.java","content":"package com.example.shortener;

import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.net.URI;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler({InvalidUrlException.class, MethodArgumentNotValidException.class,
            HttpMessageNotReadableException.class})
    public ProblemDetail badRequest(Exception exception, HttpServletRequest request) {
        String detail;
        if (exception instanceof InvalidUrlException) {
            detail = exception.getMessage();
        } else if (exception instanceof MethodArgumentNotValidException validation
                && validation.getBindingResult().getFieldError() != null) {
            detail = validation.getBindingResult().getFieldError().getDefaultMessage();
        } else {
            detail = "request body must contain a valid JSON object with a url field";
        }
        return problem(HttpStatus.BAD_REQUEST, detail, request);
    }

    @ExceptionHandler(LinkNotFoundException.class)
    public ProblemDetail notFound(LinkNotFoundException exception, HttpServletRequest request) {
        return problem(HttpStatus.NOT_FOUND, exception.getMessage(), request);
    }

    @ExceptionHandler(CodeGenerationException.class)
    public ProblemDetail unavailable(HttpServletRequest request) {
        return problem(HttpStatus.SERVICE_UNAVAILABLE,
                "the service could not generate a unique short code", request);
    }

    @ExceptionHandler(Exception.class)
    public ProblemDetail internalError(HttpServletRequest request) {
        return problem(HttpStatus.INTERNAL_SERVER_ERROR,
                "an unexpected server error occurred", request);
    }

    private ProblemDetail problem(HttpStatus status, String detail, HttpServletRequest request) {
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(status, detail);
        problem.setInstance(URI.create(request.getRequestURI()));
        return problem;
    }
}
