{"files":[{"path":"src/test/java/com/example/shortener/UrlShortenerApplicationTests.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.util.Set;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.stream.IntStream;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;

@SpringBootTest
@AutoConfigureMockMvc
class UrlShortenerApplicationTests {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;

    @Test
    void contextLoads() {
        assertThat(mockMvc).isNotNull();
    }

    @Test
    void createsHttpLinkWithExpectedResponseContract() throws Exception {
        String url = "https://example.com/path?a=1";

        mockMvc.perform(post("/api/links")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"https://example.com/path?a=1\"}"))
                .andExpect(status().isCreated())
                .andExpect(header().string("Location", org.hamcrest.Matchers.endsWith("/" + codeFromLastResponse(url))))
                .andExpect(jsonPath("$.url").value(url))
                .andExpect(jsonPath("$.code", org.hamcrest.Matchers.matchesPattern("[A-Za-z0-9_-]{7}")))
                .andExpect(jsonPath("$.shortUrl", org.hamcrest.Matchers.endsWith("/" + codeFromLastResponse(url))))
                .andExpect(jsonPath("$.clickCount").value(0));
    }

    private String codeFromLastResponse(String ignoredUrl) throws Exception {
        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"https://example.com/response-helper\"}"))
                .andReturn();
        return objectMapper.readTree(result.getResponse().getContentAsString()).get("code").asText();
    }

    @Test
    void repeatedSubmissionsCreateDistinctPersistedLinks() throws Exception {
        String body = "{\"url\":\"http://example.com/repeated-" + System.nanoTime() + "\"}";
        String first = create(body);
        String second = create(body);

        assertThat(first).hasSize(7);
        assertThat(second).hasSize(7).isNotEqualTo(first);
    }

    @Test
    void acceptsBothHttpAndHttpsUrls() throws Exception {
        create("{\"url\":\"http://example.com/http-" + System.nanoTime() + "\"}");
        create("{\"url\":\"https://example.com/https-" + System.nanoTime() + "\"}");
    }

    @Test
    void rejectsMissingBlankMalformedRelativeAndUnsupportedUrls() throws Exception {
        String[] bodies = {
                "{}",
                "{\"url\":\"\"}",
                "{\"url\":\"not a url\"}",
                "{\"url\":\"/relative/path\"}",
                "{\"url\":\"ftp://example.com/file\"}",
                "{\"url\":\"http:///hostless\"}"
        };

        for (String body : bodies) {
            mockMvc.perform(post("/api/links")
                            .contentType(MediaType.APPLICATION_JSON)
                            .content(body))
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.detail", org.hamcrest.Matchers.not(org.hamcrest.Matchers.blankOrNullString())))
                    .andExpect(jsonPath("$.title").exists());
        }
    }

    @Test
    void rejectsMalformedJsonAndMissingBody() throws Exception {
        mockMvc.perform(post("/api/links")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{not-json"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isNotEmpty());

        mockMvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isNotEmpty());
    }

    @Test
    void detailsDoNotIncrementAndFollowRedirectDoesIncrement() throws Exception {
        String url = "https://example.com/follow-" + System.nanoTime();
        String code = create("{\"url\":\"" + url + "\"}");

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.url").value(url))
                .andExpect(jsonPath("$.code").value(code))
                .andExpect(jsonPath("$.shortUrl").value(org.hamcrest.Matchers.endsWith("/" + code)))
                .andExpect(jsonPath("$.clickCount").value(0));
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(0));

        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(2));
    }

    @Test
    void unknownCodesReturnNotFoundWithoutChangingExistingLinks() throws Exception {
        String code = create("{\"url\":\"https://example.com/unknown-check-" + System.nanoTime() + "\"}");

        mockMvc.perform(get("/doesnotexist"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail").isNotEmpty());
        mockMvc.perform(get("/api/links/not-found-" + System.nanoTime()))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail").isNotEmpty());
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(0));
    }

    @Test
    void concurrentFollowsDoNotLoseClickIncrements() throws Exception {
        String url = "https://example.com/concurrent-" + System.nanoTime();
        String code = create("{\"url\":\"" + url + "\"}");
        int follows = 12;
        ExecutorService executor = Executors.newFixedThreadPool(follows);
        try {
            Set<Future<Integer>> results = IntStream.range(0, follows)
                    .mapToObj(i -> (Callable<Integer>) () -> mockMvc.perform(get("/{code}", code))
                            .andReturn().getResponse().getStatus())
                    .map(executor::submit)
                    .collect(java.util.stream.Collectors.toSet());
            for (Future<Integer> result : results) {
                assertThat(result.get()).isEqualTo(302);
            }
        } finally {
            executor.shutdownNow();
        }

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(follows));
    }

    private String create(String body) throws Exception {
        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(body))
                .andExpect(status().isCreated())
                .andReturn();
        JsonNode json = objectMapper.readTree(result.getResponse().getContentAsString());
        assertThat(json.get("url").asText()).isNotBlank();
        return json.get("code").asText();
    }
}
