"},{"path":"src/test/java/com/example/shortener/LinkServiceTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.Optional;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.dao.DataIntegrityViolationException;

@ExtendWith(MockitoExtension.class)
class LinkServiceTest {

    @Mock
    private LinkRepository repository;

    @Mock
    private ShortCodeGenerator generator;

    @InjectMocks
    private LinkService service;

    @Test
    void retriesWhenGeneratedCodeAlreadyExists() {
        when(generator.generate()).thenReturn("AAAAAAA", "BBBBBBB");
        when(repository.existsByCode("AAAAAAA")).thenReturn(true);
        Link saved = new Link("https://example.com", "BBBBBBB");
        when(repository.saveAndFlush(any(Link.class))).thenReturn(saved);

        Link result = service.create("https://example.com");

        assertThat(result).isSameAs(saved);
        verify(repository).existsByCode("AAAAAAA");
        verify(repository).saveAndFlush(any(Link.class));
    }

    @Test
    void retriesAfterUniqueConstraintCollision() {
        when(generator.generate()).thenReturn("AAAAAAA", "BBBBBBB");
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new DataIntegrityViolationException("duplicate"))
                .thenReturn(new Link("https://example.com", "BBBBBBB"));

        Link result = service.create("https://example.com");

        assertThat(result.getCode()).isEqualTo("BBBBBBB");
    }

    @Test
    void exhaustsBoundedRetriesWithCodeGenerationException() {
        when(generator.generate()).thenReturn("AAAAAAA");
        when(repository.existsByCode("AAAAAAA")).thenReturn(true);

        assertThatThrownBy(() -> service.create("https://example.com"))
                .isInstanceOf(CodeGenerationException.class);
    }

    @Test
    void getsKnownLinkAndRejectsUnknownLink() {
        Link link = new Link("https://example.com", "ABC123_");
        when(repository.findByCode("ABC123_")).thenReturn(Optional.of(link));

        assertThat(service.getByCode("ABC123_")).isSameAs(link);
        assertThatThrownBy(() -> service.getByCode("missing"))
                .isInstanceOf(LinkNotFoundException.class);
    }

    @Test
    void followAtomicallyIncrementsKnownLinkAndReturnsUrl() {
        Link link = new Link("https://example.com/path", "ABC123_");
        when(repository.findByCode("ABC123_")).thenReturn(Optional.of(link));

