import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.dao.DataIntegrityViolationException;

@ExtendWith(MockitoExtension.class)
class LinkServiceTest {

    @Mock
    private LinkRepository repository;

    @Mock
    private ShortCodeGenerator generator;

    @Test
    void createsNewLinkAndRetriesAUniqueCodeAfterCollision() {
        Link expected = new Link("https://example.com", "second2");
        when(generator.generate()).thenReturn("first1", "second2");
        when(repository.existsByCode("first1")).thenReturn(false);
        when(repository.existsByCode("second2")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new DataIntegrityViolationException("collision"))
                .thenReturn(expected);

        Link actual = new LinkService(repository, generator).create("https://example.com");

        assertThat(actual).isSameAs(expected);
        verify(repository).existsByCode("first1");
        verify(repository).existsByCode("second2");
    }

    @Test
    void skipsAlreadyExistingGeneratedCodes() {
        Link expected = new Link("https://example.com", "fresh22");
        when(generator.generate()).thenReturn("taken01", "fresh22");
        when(repository.existsByCode("taken01")).thenReturn(true);
        when(repository.existsByCode("fresh22")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class))).thenReturn(expected);

        assertThat(new LinkService(repository, generator).create("https://example.com")).isSameAs(expected);
        verify(repository, never()).saveAndFlush(any(Link.class));
    }

    @Test
    void getsKnownLinksAndReportsUnknownCodes() {
        Link link = new Link("https://example.com", "abc123_");
        when(repository.findByCode("abc123_")).thenReturn(java.util.Optional.of(link));

        assertThat(new LinkService(repository, generator).getByCode("abc123_")).isSameAs(link);
        when(repository.findByCode("missing")).thenReturn(java.util.Optional.empty());
        assertThatThrownBy(() -> new LinkService(repository, generator).getByCode("missing"))
                .isInstanceOf(LinkNotFoundException.class);
    }

    @Test
    void followIncrementsOnlyKnownCodesAndReturnsOriginalUrl() {
        Link link = new Link("https://example.com/target", "abc123_");
        when(repository.findByCode("abc123_")).thenReturn(java.util.Optional.of(link));
        when(repository.incrementClickCount("abc123_")).thenReturn(1);

        assertThat(new LinkService(repository, generator).follow("abc123_")).isEqualTo(link.getUrl());
        verify(repository).incrementClickCount("abc123_");

        when(repository.findByCode("unknown")).thenReturn(java.util.Optional.empty());
        assertThatThrownBy(() -> new LinkService(repository, generator).follow("unknown"))
                .isInstanceOf(LinkNotFoundException.class);
        verify(repository, never()).incrementClickCount("unknown");
    }
}
