import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.inOrder;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.Optional;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InOrder;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class LinkServiceTest {

    @Mock
    private LinkRepository repository;

    @Mock
    private ShortCodeGenerator codeGenerator;

    @Test
    void skipsAlreadyExistingGeneratedCodesAndPersistsTheNextCode() {
        when(codeGenerator.generate()).thenReturn("AAAAAAA", "BBBBBBB");
        when(repository.existsByCode("AAAAAAA")).thenReturn(true);
        when(repository.existsByCode("BBBBBBB")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenAnswer(invocation -> invocation.getArgument(0));

        Link result = new LinkService(repository, codeGenerator).create("https://example.com");

        assertThat(result.getCode()).isEqualTo("BBBBBBB");
        assertThat(result.getUrl()).isEqualTo("https://example.com");
        verify(repository, never()).saveAndFlush(any(Link.class));
        InOrder order = inOrder(repository);
        order.verify(repository).existsByCode("AAAAAAA");
        order.verify(repository).existsByCode("BBBBBBB");
        order.verify(repository).saveAndFlush(any(Link.class));
    }

    @Test
    void retriesAfterAUniqueConstraintCollision() {
        when(codeGenerator.generate()).thenReturn("AAAAAAA", "BBBBBBB");
        when(repository.existsByCode("AAAAAAA")).thenReturn(false);
        when(repository.existsByCode("BBBBBBB")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new org.springframework.dao.DataIntegrityViolationException("duplicate"))
                .thenAnswer(invocation -> invocation.getArgument(0));

        Link result = new LinkService(repository, codeGenerator).create("https://example.com");

        assertThat(result.getCode()).isEqualTo("BBBBBBB");
        verify(repository, org.mockito.Mockito.times(2)).saveAndFlush(any(Link.class));
    }

    @Test
    void throwsCapacityExceptionAfterAllCodeAttemptsCollide() {
        when(codeGenerator.generate()).thenReturn("AAAAAAA");
        when(repository.existsByCode("AAAAAAA")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new org.springframework.dao.DataIntegrityViolationException("duplicate"));

        assertThatThrownBy(() -> new LinkService(repository, codeGenerator).create("https://example.com"))
                .isInstanceOf(CodeGenerationException.class);
        verify(repository, org.mockito.Mockito.times(10)).saveAndFlush(any(Link.class));
    }

    @Test
    void detailsLookupDoesNotIncrementAndFollowUsesAtomicIncrement() {
        Link link = new Link("https://example.com/path", "ABC123_");
        when(repository.findByCode("ABC123_")).thenReturn(Optional.of(link));

        LinkService service = new LinkService(repository, codeGenerator);

        assertThat(service.getByCode("ABC123_")).isSameAs(link);
        assertThat(service.follow("ABC123_")).isEqualTo("https://example.com/path");
        verify(repository).incrementClickCount("ABC123_");
    }

    @Test
    void unknownFollowDoesNotAttemptAnIncrement() {
        when(repository.findByCode("MISSING")).thenReturn(Optional.empty());

        assertThatThrownBy(() -> new LinkService(repository, codeGenerator).follow("MISSING"))
                .isInstanceOf(LinkNotFoundException.class);
        verify(repository, never()).incrementClickCount(any(String.class));
    }
}
