import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;

@SpringBootTest
@AutoConfigureMockMvc
class UrlShortenerApplicationTests {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;

    @Autowired
    private LinkRepository repository;

    @Test
    void createsAValidHttpLinkWithContractFields() throws Exception {
        String url = "https://example.com/path?a=1&unique=" + UUID.randomUUID();

        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.url").value(url))
                .andExpect(jsonPath("$.code").value(org.hamcrest.Matchers.matchesPattern("[A-Za-z0-9_-]{7}")))
                .andExpect(jsonPath("$.shortUrl").value(org.hamcrest.Matchers.endsWith("/")))
                .andExpect(jsonPath("$.clickCount").value(0))
                .andReturn();

        JsonNode body = objectMapper.readTree(result.getResponse().getContentAsString());
        assertThat(body.get("shortUrl").asString()).endsWith("/" + body.get("code").asString());
        assertThat(repository.findByCode(body.get("code").asString())).isPresent();
    }

    @Test
    void repeatedSubmissionsAndBothSupportedSchemesCreateDistinctLinks() throws Exception {
        String repeated = "http://example.com/repeated/" + UUID.randomUUID();
        String first = create(repeated);
        String second = create(repeated);
        String https = create("https://example.com/secure/" + UUID.randomUUID());

        assertThat(first).matches("[A-Za-z0-9_-]{7}");
        assertThat(second).matches("[A-Za-z0-9_-]{7}");
        assertThat(https).matches("[A-Za-z0-9_-]{7}");
        assertThat(second).isNotEqualTo(first);
        assertThat(repository.findByCode(first)).isPresent();
        assertThat(repository.findByCode(second)).isPresent();
    }

    @Test
    void invalidRequestsReturnProblemDetailsWithHumanReadableMessages() throws Exception {
        String[] bodies = {"{}", "{\"url\":\"\"}", "{\"url\":\"relative/path\"}",
                "{\"url\":\"ftp://example.com/file\"}", "{\"url\":\"not a url\"}"};

        for (String body : bodies) {
            mockMvc.perform(post("/api/links").contentType("application/json").content(body))
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.detail").isNotEmpty());
        }

        mockMvc.perform(post("/api/links").contentType("application/json").content("not-json"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isNotEmpty());

        mockMvc.perform(post("/api/links").contentType("application/json"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isNotEmpty());
    }

    @Test
    void detailsDoNotIncrementAndFollowRedirectsWithA302() throws Exception {
        String url = "https://example.com/follow/" + UUID.randomUUID();
        String code = create(url);

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.url").value(url))
                .andExpect(jsonPath("$.code").value(code))
                .andExpect(jsonPath("$.shortUrl").value(org.hamcrest.Matchers.endsWith("/" + code)))
                .andExpect(jsonPath("$.clickCount").value(0));

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(0));

        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(jsonPath("$.clickCount").value(1));
    }

    @Test
    void multipleFollowsAccumulateClicksWithoutLostUpdates() throws Exception {
        String url = "http://example.com/concurrent/" + UUID.randomUUID();
        String code = create(url);
        int numberOfFollows = 12;
        ExecutorService executor = Executors.newFixedThreadPool(numberOfFollows);
        CountDownLatch start = new CountDownLatch(1);
        try {
            List<Future<MvcResult>> results = new ArrayList<>();
            for (int i = 0; i < numberOfFollows; i++) {
                results.add(executor.submit(() -> {
                    start.await();
                    return mockMvc.perform(get("/{code}", code)).andReturn();
                }));
            }
            start.countDown();
            for (Future<MvcResult> result : results) {
