                assertThat(response.getResponse().getStatus()).isEqualTo(302);
                assertThat(response.getResponse().getHeader("Location")).isEqualTo(url);
            }
        } finally {
            executor.shutdownNow();
        }

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(numberOfFollows));
    }

    @Test
    void unknownCodesReturn404WithoutCreatingOrChangingLinks() throws Exception {
        String unknown = "ZZZ999_";
        long before = repository.count();

        mockMvc.perform(get("/{code}", unknown))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail").isNotEmpty());
        mockMvc.perform(get("/api/links/{code}", unknown))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail").isNotEmpty());

        assertThat(repository.count()).isEqualTo(before);
    }

    private String create(String url) throws Exception {
        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andReturn();
        return objectMapper.readTree(result.getResponse().getContentAsString()).get("code").asString();
    }
}
