{"files":[{"path":"src/test/java/com/example/shortener/UrlShortenerApplicationTests.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

@SpringBootTest
@AutoConfigureMockMvc
class UrlShortenerApplicationTests {

    private static final Pattern CODE_PATTERN = Pattern.compile("\\\"code\\\":\\\"([A-Za-z0-9_-]{7})\\\"");

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private LinkRepository linkRepository;

    @Test
    void createsHttpLinkWithContractFieldsAndPersistsIt() throws Exception {
        String url = "http://example.com/path?a=1";

        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andReturn();

        String body = result.getResponse().getContentAsString();
        String code = codeFrom(body);
        assertThat(body).contains("\"url\":\"" + url + "\"")
                .contains("\"shortUrl\":\"http://localhost/" + code + "\"")
                .contains("\"clickCount\":0");
        assertThat(code).matches("[A-Za-z0-9_-]{7}");
        assertThat(linkRepository.findByCode(code)).isPresent();
    }

    @Test
    void acceptsHttpsAndCreatesDistinctCodesForRepeatedUrls() throws Exception {
        String url = "https://example.com/repeated";

        String first = codeFrom(mockMvc.perform(post("/api/links")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());
        String second = codeFrom(mockMvc.perform(post("/api/links")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());

        assertThat(first).matches("[A-Za-z0-9_-]{7}");
        assertThat(second).matches("[A-Za-z0-9_-]{7}").isNotEqualTo(first);
        assertThat(linkRepository.findByCode(first)).isPresent();
        assertThat(linkRepository.findByCode(second)).isPresent();
    }

    @Test
    void rejectsMissingBlankMalformedRelativeAndUnsupportedUrlsWithReadableErrors() throws Exception {
        List<String> bodies = List.of(
                "{}",
                "{\"url\":\"\"}",
                "{\"url\":\"not a url\"}",
                "{\"url\":\"/relative/path\"}",
                "{\"url\":\"ftp://example.com/file\"}",
                "{\"url\":\"http:///missing-host\"}");

        for (String body : bodies) {
            MvcResult result = mockMvc.perform(post("/api/links")
                            .contentType(MediaType.APPLICATION_JSON)
                            .content(body))
                    .andExpect(status().isBadRequest())
                    .andReturn();
            assertThat(result.getResponse().getContentAsString()).containsPattern("(?s).*(detail|message).*\\\\S.*");
        }

        MvcResult malformed = mockMvc.perform(post("/api/links")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{not-json"))
                .andExpect(status().isBadRequest())
                .andReturn();
        assertThat(malformed.getResponse().getContentAsString()).containsPattern("(?s).*\\\\S.*");
    }

    @Test
    void detailsDoNotIncrementAndFollowRedirectIncrementsCount() throws Exception {
        String url = "https://example.com/follow-me";
        String code = create(url);

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk());
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(result -> assertThat(result.getResponse().getContentAsString()).contains("\"clickCount\":0"));

        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(result -> assertThat(result.getResponse().getContentAsString()).contains("\"clickCount\":2"));
    }

    @Test
    void unknownCodesReturnJson404WithoutChangingExistingLinks() throws Exception {
        String code = create("http://example.com/unknown-check");

        mockMvc.perform(get("/ZZz_-0Q"))
                .andExpect(status().isNotFound())
                .andExpect(result -> assertThat(result.getResponse().getContentAsString()).containsPattern("(?s).*\\\\S.*"));
        mockMvc.perform(get("/api/links/ZZz_-0Q"))
                .andExpect(status().isNotFound())
                .andExpect(result -> assertThat(result.getResponse().getContentAsString()).containsPattern("(?s).*\\\\S.*"));
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(result -> assertThat(result.getResponse().getContentAsString()).contains("\"clickCount\":0"));
    }

    @Test
    void concurrentFollowsCountEverySuccessfulRedirect() throws Exception {
        String url = "http://example.com/concurrent";
        String code = create(url);
        int requests = 16;
        ExecutorService executor = Executors.newFixedThreadPool(requests);
        try {
            List<java.util.concurrent.Callable<MvcResult>> tasks = new ArrayList<>();
            for (int i = 0; i < requests; i++) {
                tasks.add(() -> mockMvc.perform(get("/{code}", code)).andReturn());
            }
            List<Future<MvcResult>> results = executor.invokeAll(tasks);
            long successful = 0;
            for (Future<MvcResult> future : results) {
                MvcResult result = future.get();
                if (result.getResponse().getStatus() == 302) {
                    successful++;
                    assertThat(result.getResponse().getHeader("Location")).isEqualTo(url);
                }
            }

            assertThat(successful).isEqualTo(requests);
            mockMvc.perform(get("/api/links/{code}", code))
                    .andExpect(status().isOk())
                    .andExpect(result -> assertThat(result.getResponse().getContentAsString())
                            .contains("\"clickCount\":" + requests));
        } finally {
            executor.shutdownNow();
        }
    }

    private String create(String url) throws Exception {
        return codeFrom(mockMvc.perform(post("/api/links")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());
    }

    private String codeFrom(String body) {
        Matcher matcher = CODE_PATTERN.matcher(body);
        assertThat(matcher.find()).as("response contains a seven-character code: %s", body).isTrue();
        return matcher.group(1);
    }
}
