        assertThatCode(() -> validator.validate(url)).doesNotThrowAnyException();
    }

    @ParameterizedTest
    @MethodSource("invalidUrls")
    void rejectsMissingMalformedRelativeHostlessAndUnsupportedUrls(String url) {
        assertThatThrownBy(() -> validator.validate(url))
                .isInstanceOf(InvalidUrlException.class)
                .hasMessageContaining("URL");
    }

    private static Stream<Arguments> validUrls() {
        return Stream.of(
                Arguments.of("http://example.com"),
                Arguments.of("https://example.com/path?a=1#fragment"),
                Arguments.of("HTTP://EXAMPLE.COM:8080/path"));
    }

    private static Stream<Arguments> invalidUrls() {
        return Stream.of(
                Arguments.of((String) null),
                Arguments.of(""),
                Arguments.of("   "),
                Arguments.of("not a URL"),
                Arguments.of("relative/path"),
                Arguments.of("ftp://example.com/file"),
                Arguments.of("http:///missing-host"),
                Arguments.of("https://"));
    }
}
"},{"path":"src/test/java/com/example/shortener/LinkServiceTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.inOrder;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.Optional;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InOrder;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class LinkServiceTest {

    @Mock
    private LinkRepository repository;

    @Mock
    private ShortCodeGenerator generator;

    @Test
    void retriesAfterAnExistingCodeAndPersistsTheNextGeneratedCode() {
        when(generator.generate()).thenReturn("AAAAAAA", "BBBBBBB");
        when(repository.existsByCode("AAAAAAA")).thenReturn(true);
        when(repository.existsByCode("BBBBBBB")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class))).thenAnswer(invocation -> invocation.getArgument(0));

        Link result = new LinkService(repository, generator).create("https://example.com");

        assertThat(result.getCode()).isEqualTo("BBBBBBB");
        verify(repository, never()).saveAndFlush(new Link("https://example.com", "AAAAAAA"));
        verify(repository).saveAndFlush(any(Link.class));
    }

    @Test
    void retriesAfterDatabaseCollisionAndEventuallySucceeds() {
        when(generator.generate()).thenReturn("AAAAAAA", "BBBBBBB");
        when(repository.existsByCode(any())).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new org.springframework.dao.DataIntegrityViolationException("duplicate"))
                .thenAnswer(invocation -> invocation.getArgument(0));

        Link result = new LinkService(repository, generator).create("http://example.com");

        assertThat(result.getCode()).isEqualTo("BBBBBBB");
        verify(repository, org.mockito.Mockito.times(2)).saveAndFlush(any(Link.class));
    }

    @Test
    void throwsCapacityExceptionAfterBoundedCollisionAttempts() {
        when(generator.generate()).thenReturn("AAAAAAA");
        when(repository.existsByCode("AAAAAAA")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new org.springframework.dao.DataIntegrityViolationException("duplicate"));

        assertThatThrownBy(() -> new LinkService(repository, generator).create("http://example.com"))
                .isInstanceOf(CodeGenerationException.class);
        verify(repository, org.mockito.Mockito.times(10)).saveAndFlush(any(Link.class));
    }

    @Test
    void getsKnownLinkAndRejectsUnknownLink() {
        Link link = new Link("https://example.com", "ABC1234");
        when(repository.findByCode("ABC1234")).thenReturn(Optional.of(link));
        when(repository.findByCode("missing")).thenReturn(Optional.empty());
        LinkService service = new LinkService(repository, generator);

        assertThat(service.getByCode("ABC1234")).isSameAs(link);
        assertThatThrownBy(() -> service.getByCode("missing")).isInstanceOf(LinkNotFoundException.class);
    }

    @Test
    void followChecksExistenceThenAtomicallyIncrementsAndReturnsUrl() {
        Link link = new Link("https://example.com/destination", "ABC1234");
        when(repository.findByCode("ABC1234")).thenReturn(Optional.of(link));

        String url = new LinkService(repository, generator).follow("ABC1234");

        assertThat(url).isEqualTo("https://example.com/destination");
        InOrder order = inOrder(repository);
        order.verify(repository).findByCode("ABC1234");
        order.verify(repository).incrementClickCount("ABC1234");
    }

    @Test
    void followDoesNotIncrementUnknownCode() {
        when(repository.findByCode("missing")).thenReturn(Optional.empty());

        assertThatThrownBy(() -> new LinkService(repository, generator).follow("missing"))
                .isInstanceOf(LinkNotFoundException.class);
        verify(repository, never()).incrementClickCount("missing");
    }
}
