{"files":[{"path":"src/test/java/com/example/shortener/UrlShortenerApplicationTests.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

import java.util.Optional;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Stream;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;
import org.mockito.InOrder;
import org.springframework.dao.DataIntegrityViolationException;

class UrlShortenerApplicationTests {

    private final UrlValidator validator = new UrlValidator();

    @ParameterizedTest
    @MethodSource("validUrls")
    void acceptsAbsoluteHttpAndHttpsUrls(String url) {
        validator.validate(url);
    }

    static Stream<Arguments> validUrls() {
        return Stream.of(
                Arguments.of("http://example.com"),
                Arguments.of("https://example.com/path?a=1#fragment"),
                Arguments.of("HTTP://example.com:8080/path"));
    }

    @ParameterizedTest
    @MethodSource("invalidUrls")
    void rejectsMissingMalformedRelativeHostlessAndUnsupportedUrls(String url) {
        assertThatThrownBy(() -> validator.validate(url))
                .isInstanceOf(InvalidUrlException.class)
                .hasMessageContaining("absolute");
    }

    static Stream<Arguments> invalidUrls() {
        return Stream.of(
                Arguments.of((String) null),
                Arguments.of(""),
                Arguments.of("   "),
                Arguments.of("not a url"),
                Arguments.of("/relative/path"),
                Arguments.of("ftp://example.com/file"),
                Arguments.of("http:///missing-host"),
                Arguments.of("https://"));
    }

    @Test
    void generatedCodesAreSevenCharactersAndUrlSafe() {
        ShortCodeGenerator generator = new ShortCodeGenerator();

        for (int i = 0; i < 100; i++) {
            String code = generator.generate();
            assertThat(code).hasSize(7).matches("[A-Za-z0-9_-]{7}");
        }
    }

    @Test
    void serviceCreatesAZeroClickLink() {
        LinkRepository repository = mock(LinkRepository.class);
        ShortCodeGenerator generator = mock(ShortCodeGenerator.class);
        when(generator.generate()).thenReturn("Ab3_xY9");
        when(repository.existsByCode("Ab3_xY9")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class))).thenAnswer(invocation -> invocation.getArgument(0));

        Link link = new LinkService(repository, generator).create("https://example.com/a");

        assertThat(link.getUrl()).isEqualTo("https://example.com/a");
        assertThat(link.getCode()).isEqualTo("Ab3_xY9");
        assertThat(link.getClickCount()).isZero();
        verify(repository).saveAndFlush(any(Link.class));
    }

    @Test
    void serviceRetriesWhenGeneratedCodeCollides() {
        LinkRepository repository = mock(LinkRepository.class);
        ShortCodeGenerator generator = mock(ShortCodeGenerator.class);
        when(generator.generate()).thenReturn("AAAAAAA", "BBBBBBB");
        when(repository.existsByCode("AAAAAAA")).thenReturn(true);
        when(repository.existsByCode("BBBBBBB")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class))).thenAnswer(invocation -> invocation.getArgument(0));

        Link link = new LinkService(repository, generator).create("http://example.com");

        assertThat(link.getCode()).isEqualTo("BBBBBBB");
        verify(repository, never()).saveAndFlush(argThat(saved -> "AAAAAAA".equals(saved.getCode())));
        verify(repository).saveAndFlush(argThat(saved -> "BBBBBBB".equals(saved.getCode())));
    }

    @Test
    void serviceRetriesAfterDatabaseUniqueConstraintCollision() {
        LinkRepository repository = mock(LinkRepository.class);
        ShortCodeGenerator generator = mock(ShortCodeGenerator.class);
        when(generator.generate()).thenReturn("AAAAAAA", "BBBBBBB");
        when(repository.existsByCode(any())).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new DataIntegrityViolationException("duplicate code"))
                .thenAnswer(invocation -> invocation.getArgument(0));

        Link link = new LinkService(repository, generator).create("https://example.com");

        assertThat(link.getCode()).isEqualTo("BBBBBBB");
        verify(repository, times(2)).saveAndFlush(any(Link.class));
    }

    @Test
    void serviceThrowsCapacityExceptionAfterTenFailedAttempts() {
        LinkRepository repository = mock(LinkRepository.class);
        ShortCodeGenerator generator = mock(ShortCodeGenerator.class);
        when(generator.generate()).thenReturn("AAAAAAA");
        when(repository.existsByCode("AAAAAAA")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new DataIntegrityViolationException("duplicate code"));

        assertThatThrownBy(() -> new LinkService(repository, generator).create("http://example.com"))
                .isInstanceOf(CodeGenerationException.class);
        verify(repository, times(10)).saveAndFlush(any(Link.class));
    }

    @Test
    void serviceReturnsOriginalUrlAndAtomicallyRequestsOneIncrement() {
        LinkRepository repository = mock(LinkRepository.class);
        ShortCodeGenerator generator = mock(ShortCodeGenerator.class);
        Link link = new Link("https://example.com/original", "Ab3_xY9");
        when(repository.findByCode("Ab3_xY9")).thenReturn(Optional.of(link));
        when(repository.incrementClickCount("Ab3_xY9")).thenReturn(1);

        String url = new LinkService(repository, generator).follow("Ab3_xY9");

        assertThat(url).isEqualTo("https://example.com/original");
        InOrder order = inOrder(repository);
        order.verify(repository).findByCode("Ab3_xY9");
        order.verify(repository).incrementClickCount("Ab3_xY9");
    }

    @Test
    void serviceDoesNotIncrementUnknownCode() {
        LinkRepository repository = mock(LinkRepository.class);
        when(repository.findByCode("missing")).thenReturn(Optional.empty());

        assertThatThrownBy(() -> new LinkService(repository, mock(ShortCodeGenerator.class)).follow("missing"))
                .isInstanceOf(LinkNotFoundException.class);
        verify(repository, never()).incrementClickCount(any());
    }
}
"},{"path":"src/test/java/com/example/shortener/LinkHttpIntegrationTests.java","content":"package com.example.shortener;

import static org.hamcrest.Matchers.hasLength;
import static org.hamcrest.Matchers.matchesPattern;
import static org.hamcrest.Matchers.not;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

@SpringBootTest
@AutoConfigureMockMvc
class LinkHttpIntegrationTests {

    private static final Pattern CODE = Pattern.compile("\\\"code\\\":\\\"([^\\\"]+)\\\"");

    @Autowired
    private MockMvc mockMvc;

    @Test
    void createsHttpLinkWithContractResponse() throws Exception {
        String url = "https://example.com/path?a=1";

        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"https://example.com/path?a=1\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.url").value(url))
                .andExpect(jsonPath("$.code", hasLength(7)))
                .andExpect(jsonPath("$.code", matchesPattern("[A-Za-z0-9_-]{7}")))
                .andExpect(jsonPath("$.shortUrl").value(matchesPattern(".*/[A-Za-z0-9_-]{7}")))
                .andExpect(jsonPath("$.clickCount").value(0))
                .andReturn();

        String code = codeFrom(result);
        org.assertj.core.api.Assertions.assertThat(code).hasSize(7);
    }

    @Test
    void createsDistinctLinksForRepeatedAndDifferentUrls() throws Exception {
        String first = create("https://example.com/repeated");
        String second = create("https://example.com/repeated");
        String third = create("http://example.org/other");

        org.assertj.core.api.Assertions.assertThat(first).isNotEqualTo(second).isNotEqualTo(third);
        org.assertj.core.api.Assertions.assertThat(second).isNotEqualTo(third);
    }

    @Test
    void acceptsBothHttpAndHttps() throws Exception {
        mockMvc.perform(post("/api/links").contentType("application/json")
                        .content("{\"url\":\"http://example.com/a\"}"))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/api/links").contentType("application/json")
                        .content("{\"url\":\"https://example.com/b\"}"))
                .andExpect(status().isCreated());
    }

    @Test
    void rejectsAllInvalidCreationRequestsWithHumanReadableProblemDetails() throws Exception {
        List<String> bodies = List.of(
                "{}",
                "{\"url\":\"\"}",
                "{\"url\":\"not a url\"}",
                "{\"url\":\"/relative\"}",
                "{\"url\":\"ftp://example.com/file\"}",
                "{\"url\":\"http:///hostless\"}",
                "{\"url\":");

        for (String body : bodies) {
            mockMvc.perform(post("/api/links").contentType("application/json").content(body))
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.detail").isString())
                    .andExpect(jsonPath("$.detail", not("")));
        }

        mockMvc.perform(post("/api/links").contentType("application/json"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isString());
    }

    @Test
    void detailsAreReadableWithoutChangingClickCount() throws Exception {
        String code = create("https://example.com/details");

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.url").value("https://example.com/details"))
                .andExpect(jsonPath("$.code").value(code))
                .andExpect(jsonPath("$.shortUrl").value("http://localhost/" + code))
                .andExpect(jsonPath("$.clickCount").value(0));
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(0));
    }

    @Test
    void followsKnownCodeWithRedirectAndCountsMultipleFollows() throws Exception {
        String url = "https://example.com/follow";
        String code = create(url);

        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(jsonPath("$.clickCount").value(2));
    }

    @Test
    void unknownCodesReturnNotFoundForBothEndpoints() throws Exception {
        String unknown = "Zz9_-xQ";
        mockMvc.perform(get("/{code}", unknown))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail").isString())
                .andExpect(jsonPath("$.detail", not("")));
        mockMvc.perform(get("/api/links/{code}", unknown))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail").isString())
                .andExpect(jsonPath("$.detail", not("")));
    }

    @Test
    void concurrentFollowsDoNotLoseClickIncrements() throws Exception {
        String code = create("https://example.com/concurrent");
        int follows = 8;
        ExecutorService executor = Executors.newFixedThreadPool(follows);
        try {
            List<Callable<MvcResult>> tasks = new ArrayList<>();
            for (int i = 0; i < follows; i++) {
                tasks.add(() -> mockMvc.perform(get("/{code}", code)).andReturn());
            }
            List<Future<MvcResult>> results = executor.invokeAll(tasks);
            for (Future<MvcResult> result : results) {
                org.assertj.core.api.Assertions.assertThat(result.get().getResponse().getStatus()).isEqualTo(302);
                org.assertj.core.api.Assertions.assertThat(result.get().getResponse().getHeader("Location"))
                        .isEqualTo("https://example.com/concurrent");
            }
        } finally {
            executor.shutdownNow();
        }

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(follows));
    }

    private String create(String url) throws Exception {
        String escaped = url.replace("\\", "\\\\").replace("\"", "\\\"");
        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + escaped + "\"}"))
                .andExpect(status().isCreated())
                .andReturn();
        return codeFrom(result);
    }

    private String codeFrom(MvcResult result) {
        Matcher matcher = CODE.matcher(result.getResponse().getContentAsString());
        org.assertj.core.api.Assertions.assertThat(matcher.find()).isTrue();
        return matcher.group(1);
    }
}
