@SpringBootTest
class LinkRepositoryIntegrationTests {

    @Autowired
    private LinkRepository repository;

    @Test
    void persistsAndRetrievesJpaEntitiesByUniqueCode() {
        String code = "Jpa_" + (System.nanoTime() % 1000);
        code = String.format("%-7s", code).replace(' ', 'x');
        Link saved = repository.saveAndFlush(new Link("https://example.com/jpa", code));

        Link loaded = repository.findByCode(saved.getCode()).orElseThrow();

        assertThat(loaded.getId()).isNotNull();
        assertThat(loaded.getUrl()).isEqualTo("https://example.com/jpa");
        assertThat(loaded.getCode()).isEqualTo(saved.getCode());
        assertThat(loaded.getClickCount()).isZero();
        assertThat(repository.existsByCode(saved.getCode())).isTrue();
    }
}
