{"files":[{"path":"src/test/java/com/example/shortener/UrlValidatorTests.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class UrlValidatorTests {

    private UrlValidator validator;

    @BeforeEach
    void setUp() {
        validator = new UrlValidator();
    }

    @Test
    void acceptsAbsoluteHttpAndHttpsUrls() {
        assertThatCode(() -> validator.validate("http://example.com/path?a=1"))
                .doesNotThrowAnyException();
        assertThatCode(() -> validator.validate("HTTPS://example.com/path"))
                .doesNotThrowAnyException();
    }

    @ParameterizedTest
    @ValueSource(strings = {
            "",
            "   ",
            "example.com/path",
            "/relative/path",
            "ftp://example.com/file",
            "mailto:user@example.com",
            "http://",
            "https:///missing-host",
            "http://[not-a-valid-host"
    })
    void rejectsMissingMalformedRelativeHostlessAndUnsupportedUrls(String value) {
        assertThatThrownBy(() -> validator.validate(value))
                .isInstanceOf(InvalidUrlException.class)
                .hasMessageContaining("url");
    }

    @Test
    void rejectsNullUrlWithHumanReadableMessage() {
        assertThatThrownBy(() -> validator.validate(null))
                .isInstanceOf(InvalidUrlException.class)
                .hasMessage("url is required and must not be blank");
    }
}
"},{"path":"src/test/java/com/example/shortener/ShortCodeAndLinkServiceTests.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.atLeastOnce;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Pattern;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.dao.DataIntegrityViolationException;

@ExtendWith(MockitoExtension.class)
class ShortCodeAndLinkServiceTests {

    private static final Pattern URL_SAFE_CODE = Pattern.compile("[A-Za-z0-9_-]{7}");

    @Mock
    private LinkRepository repository;

    @Mock
    private ShortCodeGenerator codeGenerator;

    @InjectMocks
    private LinkService service;

    @Test
    void generatorProducesSevenCryptographicallyRandomUrlSafeCharacters() {
        ShortCodeGenerator generator = new ShortCodeGenerator();
        Set<String> codes = ConcurrentHashMap.newKeySet();

        for (int i = 0; i < 100; i++) {
            String code = generator.generate();
            assertThat(code).matches(URL_SAFE_CODE);
            codes.add(code);
        }

        assertThat(codes).hasSize(100);
    }

    @Test
    void createPersistsNewLinkWithGeneratedCode() {
        Link persisted = new Link("https://example.com/a", "Abc123_");
        when(codeGenerator.generate()).thenReturn("Abc123_");
        when(repository.existsByCode("Abc123_")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class))).thenReturn(persisted);

        Link result = service.create("https://example.com/a");

        assertThat(result).isSameAs(persisted);
        verify(repository).saveAndFlush(any(Link.class));
    }

    @Test
    void createRetriesAfterAUniqueCodeCollision() {
        Link persisted = new Link("https://example.com/a", "Second_");
        when(codeGenerator.generate()).thenReturn("First_1", "Second_");
        when(repository.existsByCode("First_1")).thenReturn(false);
        when(repository.existsByCode("Second_")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new DataIntegrityViolationException("duplicate code"))
                .thenReturn(persisted);

        Link result = service.create("https://example.com/a");

        assertThat(result.getCode()).isEqualTo("Second_");
        verify(repository, atLeastOnce()).saveAndFlush(any(Link.class));
    }

    @Test
    void createSkipsCodesAlreadyPresentInRepository() {
        Link persisted = new Link("https://example.com/a", "NewCode");
        when(codeGenerator.generate()).thenReturn("Taken01", "NewCode");
        when(repository.existsByCode("Taken01")).thenReturn(true);
        when(repository.existsByCode("NewCode")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class))).thenReturn(persisted);

        Link result = service.create("https://example.com/a");

        assertThat(result.getCode()).isEqualTo("NewCode");
        verify(repository).existsByCode("Taken01");
        verify(repository).saveAndFlush(any(Link.class));
    }

    @Test
    void createFailsAfterBoundedCollisionRetries() {
        when(codeGenerator.generate()).thenReturn("Taken01");
        when(repository.existsByCode("Taken01")).thenReturn(true);

        assertThatThrownBy(() -> service.create("https://example.com/a"))
                .isInstanceOf(CodeGenerationException.class);

        verify(repository, never()).saveAndFlush(any(Link.class));
    }

    @Test
    void getByCodeReturnsKnownLink() {
        Link link = new Link("https://example.com/a", "Known01");
        when(repository.findByCode("Known01")).thenReturn(Optional.of(link));

        assertThat(service.getByCode("Known01")).isSameAs(link);
    }

    @Test
    void getByCodeThrowsForUnknownCode() {
        when(repository.findByCode("Missing")).thenReturn(Optional.empty());

        assertThatThrownBy(() -> service.getByCode("Missing"))
                .isInstanceOf(LinkNotFoundException.class)
                .hasMessageContaining("Missing");
    }

    @Test
    void followIncrementsKnownLinkAndReturnsOriginalUrl() {
        Link link = new Link("https://example.com/original", "Known01");
        when(repository.findByCode("Known01")).thenReturn(Optional.of(link));
        when(repository.incrementClickCount("Known01")).thenReturn(1);

        assertThat(service.follow("Known01")).isEqualTo("https://example.com/original");

        verify(repository).incrementClickCount("Known01");
    }

    @Test
    void followDoesNotIncrementUnknownLink() {
        when(repository.findByCode("Missing")).thenReturn(Optional.empty());

        assertThatThrownBy(() -> service.follow("Missing"))
                .isInstanceOf(LinkNotFoundException.class);

        verify(repository, never()).incrementClickCount("Missing");
    }
}
"},{"path":"src/test/java/com/example/shortener/LinkHttpIntegrationTests.java","content":"package com.example.shortener;

import static org.hamcrest.Matchers.endsWith;
import static org.hamcrest.Matchers.greaterThanOrEqualTo;
import static org.hamcrest.Matchers.matchesPattern;
import static org.hamcrest.Matchers.notNullValue;
import static org.hamcrest.Matchers.not;
import static org.hamcrest.Matchers.is;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

import com.jayway.jsonpath.JsonPath;

@SpringBootTest
@AutoConfigureMockMvc
class LinkHttpIntegrationTests {

    @Autowired
    private MockMvc mockMvc;

    @Test
    void createsHttpLinkWithStableResponseSchema() throws Exception {
        String url = "https://example.com/path?a=1";

        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.url").value(url))
                .andExpect(jsonPath("$.code", matchesPattern("[A-Za-z0-9_-]{7}")))
                .andExpect(jsonPath("$.shortUrl", endsWith("/" + codeFrom(result))))
                .andExpect(jsonPath("$.clickCount").value(0))
                .andReturn();

        String code = codeFrom(result);
        org.assertj.core.api.Assertions.assertThat(result.getResponse().getHeader("Location"))
                .endsWith("/" + code);
    }

    @Test
    void repeatedSubmissionCreatesDistinctPersistedLinks() throws Exception {
        String url = "http://example.com/repeated-" + System.nanoTime();
        String first = create(url);
        String second = create(url);

        org.assertj.core.api.Assertions.assertThat(second).isNotEqualTo(first);
        mockMvc.perform(get("/api/links/" + first))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.url").value(url));
        mockMvc.perform(get("/api/links/" + second))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.url").value(url));
    }

    @Test
    void acceptsBothHttpAndHttpsUrls() throws Exception {
        create("http://example.com/http-" + System.nanoTime());
        create("https://example.com/https-" + System.nanoTime());
    }

    @Test
    void rejectsMissingBlankMalformedRelativeAndUnsupportedUrls() throws Exception {
        List<String> bodies = List.of(
                "{}",
                "{\"url\":\"\"}",
                "{\"url\":\"not a url\"}",
                "{\"url\":\"/relative\"}",
                "{\"url\":\"ftp://example.com/file\"}",
                "{\"url\":\"http://\"}");

        for (String body : bodies) {
            mockMvc.perform(post("/api/links")
                            .contentType(MediaType.APPLICATION_JSON)
                            .content(body))
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.detail", not(is(""))))
                    .andExpect(jsonPath("$.detail", notNullValue()));
        }

        mockMvc.perform(post("/api/links")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{not-json"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail", notNullValue()));
    }

    @Test
    void detailsReturnLinkWithoutChangingClickCount() throws Exception {
        String url = "https://example.com/details-" + System.nanoTime();
        String code = create(url);

        mockMvc.perform(get("/api/links/" + code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.url").value(url))
                .andExpect(jsonPath("$.code").value(code))
                .andExpect(jsonPath("$.shortUrl", endsWith("/" + code)))
                .andExpect(jsonPath("$.clickCount").value(0));
        mockMvc.perform(get("/api/links/" + code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(0));
    }

    @Test
    void followingRedirectsAndIncrementsClickCount() throws Exception {
        String url = "https://example.com/follow-" + System.nanoTime();
        String code = create(url);

        mockMvc.perform(get("/" + code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/" + code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/api/links/" + code))
                .andExpect(jsonPath("$.clickCount").value(2));
    }

    @Test
    void unknownCodesReturnJson404ForBothEndpoints() throws Exception {
        String unknown = "NoSuch" + (System.nanoTime() % 10);

        mockMvc.perform(get("/api/links/" + unknown))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail", notNullValue()));
        mockMvc.perform(get("/" + unknown))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail", notNullValue()));
    }

    @Test
    void concurrentFollowsDoNotLoseClickIncrements() throws Exception {
        String url = "https://example.com/concurrent-" + System.nanoTime();
        String code = create(url);
        int requestCount = 12;
        ExecutorService executor = Executors.newFixedThreadPool(requestCount);
        CountDownLatch ready = new CountDownLatch(requestCount);
        CountDownLatch start = new CountDownLatch(1);
        List<Callable<MvcResult>> tasks = new ArrayList<>();
        for (int i = 0; i < requestCount; i++) {
            tasks.add(() -> {
                ready.countDown();
                start.await();
                return mockMvc.perform(get("/" + code)).andReturn();
            });
        }

        List<Future<MvcResult>> futures;
        try {
            futures = new ArrayList<>();
            for (Callable<MvcResult> task : tasks) {
                futures.add(executor.submit(task));
            }
            ready.await();
            start.countDown();
            for (Future<MvcResult> future : futures) {
                org.assertj.core.api.Assertions.assertThat(future.get().getResponse().getStatus())
                        .isEqualTo(302);
            }
        } finally {
            executor.shutdownNow();
        }

        mockMvc.perform(get("/api/links/" + code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount", is(requestCount)));
    }

    private String create(String url) throws Exception {
        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andReturn();
        return codeFrom(result);
    }

    private String codeFrom(MvcResult result) {
        return JsonPath.read(result.getResponse().getContentAsString(), "$.code");
    }
}
