{"files":[{"path":"src/test/java/com/example/shortener/UrlValidatorTests.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.stream.Stream;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

class UrlValidatorTests {

    private final UrlValidator validator = new UrlValidator();

    @ParameterizedTest
    @MethodSource("validUrls")
    void acceptsAbsoluteHttpAndHttpsUrls(String url) {
        assertThatCode(() -> validator.validate(url)).doesNotThrowAnyException();
    }

    static Stream<Arguments> validUrls() {
        return Stream.of(
                Arguments.of("http://example.com"),
                Arguments.of("https://example.com/path?a=1#fragment"),
                Arguments.of("HTTP://example.com/resource"),
                Arguments.of("https://localhost:8443/shortener"));
    }

    @ParameterizedTest
    @MethodSource("invalidUrls")
    void rejectsMissingMalformedRelativeHostlessAndUnsupportedUrls(String url) {
        assertThatThrownBy(() -> validator.validate(url))
                .isInstanceOf(InvalidUrlException.class)
                .hasMessageContaining("URL");
    }

    static Stream<Arguments> invalidUrls() {
        return Stream.of(
                Arguments.of((String) null),
                Arguments.of(""),
                Arguments.of("   "),
                Arguments.of("not a url"),
                Arguments.of("/relative/path"),
                Arguments.of("ftp://example.com/file"),
                Arguments.of("https:///missing-host"),
                Arguments.of("https://"));
    }

    @Test
    void generatedCodesAreSevenCharactersAndUrlSafe() {
        ShortCodeGenerator generator = new ShortCodeGenerator();

        for (int i = 0; i < 100; i++) {
            String code = generator.generate();
            org.assertj.core.api.Assertions.assertThat(code)
                    .hasSize(7)
                    .matches("[A-Za-z0-9_-]{7}");
        }
    }
}
"},{"path":"src/test/java/com/example/shortener/LinkServiceTests.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.Optional;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.dao.DataIntegrityViolationException;

@ExtendWith(MockitoExtension.class)
class LinkServiceTests {

    @Mock
    private LinkRepository repository;

    @Mock
    private ShortCodeGenerator codeGenerator;

    @Test
    void createsAndPersistsLinkWithGeneratedCode() {
        when(codeGenerator.generate()).thenReturn("aB3_xY9");
        when(repository.existsByCode("aB3_xY9")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenAnswer(invocation -> invocation.getArgument(0));

        Link result = new LinkService(repository, codeGenerator).create("https://example.com/path");

        assertThat(result.getCode()).isEqualTo("aB3_xY9");
        assertThat(result.getUrl()).isEqualTo("https://example.com/path");
        assertThat(result.getClickCount()).isZero();
        verify(repository).saveAndFlush(any(Link.class));
    }

    @Test
    void retriesWhenGeneratedCodeAlreadyExists() {
        when(codeGenerator.generate()).thenReturn("used123", "new4567");
        when(repository.existsByCode("used123")).thenReturn(true);
        when(repository.existsByCode("new4567")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenAnswer(invocation -> invocation.getArgument(0));

        Link result = new LinkService(repository, codeGenerator).create("http://example.com");

        assertThat(result.getCode()).isEqualTo("new4567");
        verify(repository, never()).saveAndFlush(any(Link.class));
    }

    @Test
    void retriesAfterDatabaseUniqueConstraintCollision() {
        when(codeGenerator.generate()).thenReturn("first01", "second2");
        when(repository.existsByCode("first01")).thenReturn(false);
        when(repository.existsByCode("second2")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new DataIntegrityViolationException("duplicate code"))
                .thenAnswer(invocation -> invocation.getArgument(0));

        Link result = new LinkService(repository, codeGenerator).create("https://example.com");

        assertThat(result.getCode()).isEqualTo("second2");
    }

    @Test
    void reportsCodeGenerationFailureAfterBoundedRetries() {
        when(codeGenerator.generate()).thenReturn("same001");
        when(repository.existsByCode("same001")).thenReturn(true);

        assertThatThrownBy(() -> new LinkService(repository, codeGenerator).create("https://example.com"))
                .isInstanceOf(CodeGenerationException.class);
    }

    @Test
    void lookupReturnsLinkWhenPresent() {
        Link link = new Link("https://example.com", "abc1234");
        when(repository.findByCode("abc1234")).thenReturn(Optional.of(link));

        assertThat(new LinkService(repository, codeGenerator).getByCode("abc1234")).isSameAs(link);
    }

    @Test
    void lookupThrowsNotFoundWhenAbsent() {
        when(repository.findByCode("missing")).thenReturn(Optional.empty());

        assertThatThrownBy(() -> new LinkService(repository, codeGenerator).getByCode("missing"))
                .isInstanceOf(LinkNotFoundException.class)
                .hasMessageContaining("missing");
    }

    @Test
    void followIncrementsKnownCodeAndReturnsOriginalUrl() {
        Link link = new Link("https://example.com/target", "abc1234");
        when(repository.findByCode("abc1234")).thenReturn(Optional.of(link));
        when(repository.incrementClickCount("abc1234")).thenReturn(1);

        String url = new LinkService(repository, codeGenerator).follow("abc1234");

        assertThat(url).isEqualTo("https://example.com/target");
        verify(repository).incrementClickCount("abc1234");
    }

    @Test
    void followDoesNotIncrementUnknownCode() {
        when(repository.findByCode("missing")).thenReturn(Optional.empty());

        assertThatThrownBy(() -> new LinkService(repository, codeGenerator).follow("missing"))
                .isInstanceOf(LinkNotFoundException.class);
        verify(repository, never()).incrementClickCount("missing");
    }
}
"},{"path":"src/test/java/com/example/shortener/LinkHttpIntegrationTests.java","content":"package com.example.shortener;

import static org.hamcrest.Matchers.endsWith;
import static org.hamcrest.Matchers.hasLength;
import static org.hamcrest.Matchers.not;
import static org.hamcrest.Matchers.notNullValue;
import static org.hamcrest.Matchers.startsWith;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

@SpringBootTest
@AutoConfigureMockMvc
class LinkHttpIntegrationTests {

    @Autowired
    private MockMvc mockMvc;

    @Test
    void createsHttpLinkWithContractFields() throws Exception {
        String url = "https://example.com/path?a=1";
        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("""
                                {"url":"https://example.com/path?a=1"}
                                """))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.url").value(url))
                .andExpect(jsonPath("$.code", hasLength(7)))
                .andExpect(jsonPath("$.code", matchesUrlSafeCode()))
                .andExpect(jsonPath("$.shortUrl", startsWith("http://localhost/")))
                .andExpect(jsonPath("$.shortUrl", endsWith("/" + codeFrom(result))))
                .andExpect(jsonPath("$.clickCount").value(0))
                .andReturn();
        org.assertj.core.api.Assertions.assertThat(result.getResponse().getStatus()).isEqualTo(201);
    }

    @Test
    void repeatedSubmissionsCreateDistinctPersistedLinks() throws Exception {
        String body = """
                {"url":"https://repeat.example/%s"}
                """.formatted(System.nanoTime());
        String first = codeFrom(mockMvc.perform(post("/api/links").contentType("application/json").content(body))
                .andExpect(status().isCreated()).andReturn());
        String second = codeFrom(mockMvc.perform(post("/api/links").contentType("application/json").content(body))
                .andExpect(status().isCreated()).andReturn());

        org.assertj.core.api.Assertions.assertThat(first).isNotEqualTo(second);
        mockMvc.perform(get("/api/links/" + first)).andExpect(status().isOk())
                .andExpect(jsonPath("$.code").value(first));
        mockMvc.perform(get("/api/links/" + second)).andExpect(status().isOk())
                .andExpect(jsonPath("$.code").value(second));
    }

    @Test
    void acceptsBothHttpAndHttps() throws Exception {
        mockMvc.perform(post("/api/links").contentType("application/json")
                        .content("""{"url":"http://example.com/plain"}"""))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/api/links").contentType("application/json")
                        .content("""{"url":"https://example.com/secure"}"""))
                .andExpect(status().isCreated());
    }

    @Test
    void rejectsInvalidRequestBodiesWithHumanReadableProblemDetails() throws Exception {
        String[] bodies = {"{}", "{\"url\":\"\"}", "{\"url\":\"relative\"}",
                "{\"url\":\"ftp://example.com/file\"}", "{\"url\":\"not a url\"}"};
        for (String body : bodies) {
            mockMvc.perform(post("/api/links").contentType("application/json").content(body))
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.detail", notNullValue()))
                    .andExpect(jsonPath("$.detail", not("")));
        }
        mockMvc.perform(post("/api/links").contentType("application/json").content("not-json"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail", notNullValue()));
        mockMvc.perform(post("/api/links").contentType("application/json"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail", notNullValue()));
    }

    @Test
    void detailsDoNotIncrementClicksAndUnknownApiCodeIsNotFound() throws Exception {
        String code = codeFrom(create("https://details.example/" + System.nanoTime()));
        mockMvc.perform(get("/api/links/" + code)).andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(0))
                .andExpect(jsonPath("$.url").value(startsWith("https://details.example/")));
        mockMvc.perform(get("/api/links/" + code)).andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(0));
        mockMvc.perform(get("/api/links/unknown1")).andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail", notNullValue()));
    }

    @Test
    void followsWith302AndAccumulatesClicks() throws Exception {
        String url = "https://follow.example/target/" + System.nanoTime();
        String code = codeFrom(create(url));
        mockMvc.perform(get("/" + code)).andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/" + code)).andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/api/links/" + code)).andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(2));
    }

    @Test
    void unknownRedirectReturns404WithoutCreatingOrIncrementingAnything() throws Exception {
        mockMvc.perform(get("/doesnotexist")).andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail", notNullValue()));
    }

    @Test
    void concurrentFollowsDoNotLoseClickIncrements() throws Exception {
        String code = codeFrom(create("https://concurrent.example/" + System.nanoTime()));
        int follows = 12;
        ExecutorService executor = Executors.newFixedThreadPool(follows);
        try {
            List<Callable<MvcResult>> tasks = new ArrayList<>();
            for (int i = 0; i < follows; i++) {
                tasks.add(() -> mockMvc.perform(get("/" + code)).andExpect(status().isFound()).andReturn());
            }
            List<Future<MvcResult>> results = executor.invokeAll(tasks);
            for (Future<MvcResult> result : results) {
                org.assertj.core.api.Assertions.assertThat(result.get().getResponse().getHeader("Location"))
                        .isEqualTo("https://concurrent.example/" + code.substring(0, 0));
            }
        } finally {
            executor.shutdownNow();
        }
        mockMvc.perform(get("/api/links/" + code)).andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(follows));
    }

    private MvcResult create(String url) throws Exception {
        return mockMvc.perform(post("/api/links").contentType("application/json")
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated()).andReturn();
    }

    private static String codeFrom(MvcResult result) throws Exception {
        String content = result.getResponse().getContentAsString();
        int start = content.indexOf("\"code\":\"") + 9;
        int end = content.indexOf('"', start);
        return content.substring(start, end);
    }

    private static org.hamcrest.Matcher<String> matchesUrlSafeCode() {
        return org.hamcrest.Matchers.matchesPattern("[A-Za-z0-9_-]{7}");
    }
}
