import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.inOrder;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.Optional;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InOrder;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.dao.DataIntegrityViolationException;

@ExtendWith(MockitoExtension.class)
class LinkServiceTests {

    @Mock
    private LinkRepository repository;

    @Mock
    private ShortCodeGenerator generator;

    @Test
    void createsAndFlushesAUniqueLink() {
        LinkService service = new LinkService(repository, generator);
        Link saved = new Link("https://example.com/a", "Abc_123");
        when(generator.generate()).thenReturn("Abc_123");
        when(repository.existsByCode("Abc_123")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class))).thenReturn(saved);

        Link result = service.create("https://example.com/a");

        assertThat(result).isSameAs(saved);
        verify(repository).saveAndFlush(any(Link.class));
    }

    @Test
    void retriesWhenA generatedCodeAlreadyExists() {
        LinkService service = new LinkService(repository, generator);
        Link saved = new Link("https://example.com/a", "NewCode");
        when(generator.generate()).thenReturn("OldCode", "NewCode");
        when(repository.existsByCode("OldCode")).thenReturn(true);
        when(repository.existsByCode("NewCode")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class))).thenReturn(saved);

        Link result = service.create("https://example.com/a");

        assertThat(result.getCode()).isEqualTo("NewCode");
        verify(repository, never()).saveAndFlush(any(Link.class));
    }

    @Test
    void retriesAfterDatabaseUniqueConstraintCollision() {
        LinkService service = new LinkService(repository, generator);
        Link saved = new Link("https://example.com/a", "Second1");
        when(generator.generate()).thenReturn("First1", "Second1");
        when(repository.existsByCode("First1")).thenReturn(false);
        when(repository.existsByCode("Second1")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new DataIntegrityViolationException("duplicate"))
                .thenReturn(saved);

        assertThat(service.create("https://example.com/a")).isSameAs(saved);
    }

    @Test
    void reportsCodeGenerationFailureAfterBoundedRetries() {
        LinkService service = new LinkService(repository, generator);
        when(generator.generate()).thenReturn("Same123");
        when(repository.existsByCode("Same123")).thenReturn(true);

        assertThatThrownBy(() -> service.create("https://example.com/a"))
                .isInstanceOf(CodeGenerationException.class);
    }

    @Test
    void getsKnownLinkAndRejectsUnknownLink() {
        LinkService service = new LinkService(repository, generator);
        Link link = new Link("https://example.com/a", "Known01");
        when(repository.findByCode("Known01")).thenReturn(Optional.of(link));
        when(repository.findByCode("Missing")).thenReturn(Optional.empty());

        assertThat(service.getByCode("Known01")).isSameAs(link);
        assertThatThrownBy(() -> service.getByCode("Missing"))
                .isInstanceOf(LinkNotFoundException.class);
        verify(repository, never()).incrementClickCount("Known01");
    }

    @Test
    void followsKnownLinkByIncrementingAndReturningItsUrl() {
        LinkService service = new LinkService(repository, generator);
        Link link = new Link("https://example.com/a", "Follow1");
        when(repository.findByCode("Follow1")).thenReturn(Optional.of(link));

        assertThat(service.follow("Follow1")).isEqualTo("https://example.com/a");

        InOrder order = inOrder(repository);
        order.verify(repository).findByCode("Follow1");
        order.verify(repository).incrementClickCount("Follow1");
    }

    @Test
    void doesNotIncrementUnknownLink() {
        LinkService service = new LinkService(repository, generator);
        when(repository.findByCode("Missing")).thenReturn(Optional.empty());

        assertThatThrownBy(() -> service.follow("Missing"))
                .isInstanceOf(LinkNotFoundException.class);
        verify(repository, never()).incrementClickCount("Missing");
    }
}
"},{"path":"src/test/java/com/example/shortener/LinkHttpIntegrationTests.java","content":"package com.example.shortener;

import static org.hamcrest.Matchers.endsWith;
import static org.hamcrest.Matchers.hasSize;
import static org.hamcrest.Matchers.matchesPattern;
import static org.hamcrest.Matchers.notNullValue;
import static org.hamcrest.Matchers.startsWith;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

import com.jayway.jsonpath.JsonPath;

@SpringBootTest
@AutoConfigureMockMvc
class LinkHttpIntegrationTests {

    @Autowired
    private MockMvc mockMvc;

    @Test
    void createsHttpLinkWithContractFields() throws Exception {
        String url = "https://example.com/path?a=1";
        MvcResult result = create(url);
        String code = codeFrom(result);

        mockMvc.perform(asyncRequestFor(result))
                .andExpect(status().isCreated());
        org.assertj.core.api.Assertions.assertThat(result.getResponse().getStatus()).isEqualTo(201);
        org.assertj.core.api.Assertions.assertThat(code).matches("[A-Za-z0-9_-]{7}");
        org.assertj.core.api.Assertions.assertThat(result.getResponse().getContentAsString())
                .contains("\"url\":\"" + url + "\"")
                .contains("\"clickCount\":0")
                .contains("\"shortUrl\":\"http://localhost/" + code + "\"");
    }

    private javax.servlet.http.HttpServletRequest asyncRequestFor(MvcResult ignored) {
        return null;
    }

    @Test
    void createsDistinctCodesForRepeatedAndDifferentUrls() throws Exception {
        String first = codeFrom(create("http://example.com/repeated"));
        String second = codeFrom(create("http://example.com/repeated"));
        String third = codeFrom(create("https://example.net/other"));

        org.assertj.core.api.Assertions.assertThat(second).isNotEqualTo(first);
        org.assertj.core.api.Assertions.assertThat(third).isNotEqualTo(first).isNotEqualTo(second);
    }

    @Test
    void acceptsBothHttpAndHttps() throws Exception {
        mockMvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"http://example.com/plain\"}"))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"https://example.com/secure\"}"))
                .andExpect(status().isCreated());
    }

    @Test
    void rejectsAllInvalidCreationBodiesWithReadableProblemDetails() throws Exception {
        List<String> bodies = List.of(
                "{}",
                "{\"url\":\"\"}",
                "{\"url\":\"not a url\"}",
                "{\"url\":\"/relative\"}",
                "{\"url\":\"ftp://example.com/file\"}");
        for (String body : bodies) {
            mockMvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON).content(body))
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.detail", notNullValue()));
        }
        mockMvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail", notNullValue()));
        mockMvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail", notNullValue()));
    }

    @Test
    void retrievesDetailsWithoutChangingClickCount() throws Exception {
        String code = codeFrom(create("https://example.com/details"));

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.code").value(code))
                .andExpect(jsonPath("$.url").value("https://example.com/details"))
                .andExpect(jsonPath("$.shortUrl").value("http://localhost/" + code))
                .andExpect(jsonPath("$.clickCount").value(0));
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(0));
    }

    @Test
    void followsWithRedirectAndCountsMultipleFollows() throws Exception {
        String url = "https://example.com/follow";
        String code = codeFrom(create(url));

        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(jsonPath("$.clickCount").value(2));
    }

    @Test
    void returnsNotFoundForUnknownCodesWithoutChangingExistingLinks() throws Exception {
        String code = codeFrom(create("https://example.com/untouched"));
        String unknown = "NoSuch1";

        mockMvc.perform(get("/{code}", unknown))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail", notNullValue()));
        mockMvc.perform(get("/api/links/{code}", unknown))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail", notNullValue()));
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(jsonPath("$.clickCount").value(0));
    }

    @Test
    void concurrentFollowsDoNotLoseClickIncrements() throws Exception {
        String code = codeFrom(create("https://example.com/concurrent"));
        int requests = 12;
        ExecutorService executor = Executors.newFixedThreadPool(6);
        try {
            List<Callable<Integer>> tasks = new ArrayList<>();
            for (int i = 0; i < requests; i++) {
                tasks.add(() -> mockMvc.perform(get("/{code}", code)).andReturn().getResponse().getStatus());
            }
            List<java.util.concurrent.Future<Integer>> results = executor.invokeAll(tasks);
            for (java.util.concurrent.Future<Integer> result : results) {
                org.assertj.core.api.Assertions.assertThat(result.get()).isEqualTo(302);
            }
        } finally {
            executor.shutdownNow();
        }

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(requests));
    }

    private MvcResult create(String url) throws Exception {
        return mockMvc.perform(post("/api/links")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.code", matchesPattern("[A-Za-z0-9_-]{7}")))
                .andExpect(jsonPath("$.shortUrl", endsWith("/" + "")))
                .andExpect(jsonPath("$.clickCount").value(0))
                .andReturn();
    }

    private String codeFrom(MvcResult result) throws Exception {
        return JsonPath.read(result.getResponse().getContentAsString(), "$.code");
    }
}
