import static org.assertj.core.api.Assertions.assertThat;

import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;

import org.junit.jupiter.api.Test;

class ShortCodeGeneratorTest {

    private static final Pattern URL_SAFE_CODE = Pattern.compile("[A-Za-z0-9_-]{7}");

    @Test
    void generatesExactlySevenUrlSafeCharacters() {
        ShortCodeGenerator generator = new ShortCodeGenerator();

        for (int i = 0; i < 100; i++) {
            assertThat(generator.generate()).matches(URL_SAFE_CODE);
        }
    }

    @Test
    void generatesDistinctCodesAcrossRepeatedCalls() {
        ShortCodeGenerator generator = new ShortCodeGenerator();
        Set<String> codes = new HashSet<>();

        for (int i = 0; i < 100; i++) {
            codes.add(generator.generate());
        }

        assertThat(codes).hasSizeGreaterThan(95);
    }
}
"},{"path":"src/test/java/com/example/shortener/LinkServiceTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.Optional;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.dao.DataIntegrityViolationException;

@ExtendWith(MockitoExtension.class)
class LinkServiceTest {

    @Mock
    private LinkRepository repository;

    @Mock
    private ShortCodeGenerator codeGenerator;

    @Test
    void createsLinkWithGeneratedCode() {
        when(codeGenerator.generate()).thenReturn("Ab3_xY9");
        when(repository.existsByCode("Ab3_xY9")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class))).thenAnswer(invocation -> invocation.getArgument(0));

        Link result = new LinkService(repository, codeGenerator).create("https://example.com/path");

        assertThat(result.getUrl()).isEqualTo("https://example.com/path");
        assertThat(result.getCode()).isEqualTo("Ab3_xY9");
        assertThat(result.getClickCount()).isZero();
        verify(repository).saveAndFlush(any(Link.class));
    }

    @Test
    void retriesWhenGeneratedCodeAlreadyExists() {
        when(codeGenerator.generate()).thenReturn("AAAAAAA", "BBBBBBB");
        when(repository.existsByCode("AAAAAAA")).thenReturn(true);
        when(repository.existsByCode("BBBBBBB")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class))).thenAnswer(invocation -> invocation.getArgument(0));

        Link result = new LinkService(repository, codeGenerator).create("http://example.com");

        assertThat(result.getCode()).isEqualTo("BBBBBBB");
        verify(repository, never()).saveAndFlush(new Link("ignored", "ignored"));
    }

    @Test
    void retriesAfterDatabaseUniqueConstraintCollision() {
        when(codeGenerator.generate()).thenReturn("AAAAAAA", "BBBBBBB");
        when(repository.existsByCode("AAAAAAA")).thenReturn(false);
        when(repository.existsByCode("BBBBBBB")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new DataIntegrityViolationException("duplicate code"))
                .thenAnswer(invocation -> invocation.getArgument(0));

        Link result = new LinkService(repository, codeGenerator).create("https://example.org");

        assertThat(result.getCode()).isEqualTo("BBBBBBB");
    }

    @Test
    void throwsCapacityErrorAfterBoundedGenerationAttempts() {
        when(codeGenerator.generate()).thenReturn("AAAAAAA");
        when(repository.existsByCode("AAAAAAA")).thenReturn(false);
        when(repository.saveAndFlush(any(Link.class)))
                .thenThrow(new DataIntegrityViolationException("duplicate code"));

        assertThatThrownBy(() -> new LinkService(repository, codeGenerator).create("https://example.org"))
                .isInstanceOf(CodeGenerationException.class);
    }

    @Test
    void lookupReturnsExistingLinkWithoutIncrementing() {
        Link link = new Link("https://example.com", "Ab3_xY9");
        when(repository.findByCode("Ab3_xY9")).thenReturn(Optional.of(link));

        Link result = new LinkService(repository, codeGenerator).getByCode("Ab3_xY9");

        assertThat(result).isSameAs(link);
        verify(repository, never()).incrementClickCount("Ab3_xY9");
    }

    @Test
    void followIncrementsKnownLinkAndReturnsOriginalUrl() {
        Link link = new Link("https://example.com/target", "Ab3_xY9");
        when(repository.findByCode("Ab3_xY9")).thenReturn(Optional.of(link));
        when(repository.incrementClickCount("Ab3_xY9")).thenReturn(1);

        String result = new LinkService(repository, codeGenerator).follow("Ab3_xY9");

        assertThat(result).isEqualTo("https://example.com/target");
        verify(repository).incrementClickCount("Ab3_xY9");
    }

    @Test
    void unknownFollowDoesNotIncrement() {
        when(repository.findByCode("ZZZZZZZ")).thenReturn(Optional.empty());

        assertThatThrownBy(() -> new LinkService(repository, codeGenerator).follow("ZZZZZZZ"))
                .isInstanceOf(LinkNotFoundException.class);
        verify(repository, never()).incrementClickCount("ZZZZZZZ");
    }
}
"},{"path":"src/test/java/com/example/shortener/UrlShortenerIntegrationTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

import com.jayway.jsonpath.JsonPath;

@SpringBootTest
@AutoConfigureMockMvc
class UrlShortenerIntegrationTest {

    @Autowired
    private MockMvc mockMvc;

    @Test
    void createsHttpLinkWithStableResponseSchema() throws Exception {
        String url = "https://example.com/path?a=1";

        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.url").value(url))
                .andExpect(jsonPath("$.code").value(org.hamcrest.Matchers.matchesPattern("[A-Za-z0-9_-]{7}")))
                .andExpect(jsonPath("$.shortUrl").value(org.hamcrest.Matchers.endsWith("/" + "")))
                .andExpect(jsonPath("$.clickCount").value(0))
                .andReturn();

        String code = JsonPath.read(result.getResponse().getContentAsString(), "$.code");
        String shortUrl = JsonPath.read(result.getResponse().getContentAsString(), "$.shortUrl");
        assertThat(shortUrl).endsWith("/" + code);
    }

    @Test
    void repeatedSubmissionCreatesDistinctLinksAndBothSchemesAreAccepted() throws Exception {
        String url = "http://example.com/repeated";
        String first = createAndReadCode(url);
        String second = createAndReadCode(url);
        String httpsCode = createAndReadCode("https://example.com/secure");

        assertThat(first).hasSize(7);
        assertThat(second).hasSize(7).isNotEqualTo(first);
        assertThat(httpsCode).hasSize(7).isNotIn(first, second);
    }

    @Test
    void invalidRequestsReturnProblemDetailsWithHumanReadableMessages() throws Exception {
        mockMvc.perform(post("/api/links").contentType("application/json").content("{}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isNotEmpty());
        mockMvc.perform(post("/api/links").contentType("application/json").content("{\"url\":\"\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isNotEmpty());
        mockMvc.perform(post("/api/links").contentType("application/json").content("{\"url\":\"/relative\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isNotEmpty());
        mockMvc.perform(post("/api/links").contentType("application/json").content("{\"url\":\"ftp://example.com/file\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isNotEmpty());
        mockMvc.perform(post("/api/links").contentType("application/json").content("not-json"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isNotEmpty());
    }

    @Test
    void detailsDoNotIncrementAndUnknownApiCodeIsNotFound() throws Exception {
        String url = "https://example.com/details-only";
        String code = createAndReadCode(url);

        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.url").value(url))
                .andExpect(jsonPath("$.code").value(code))
                .andExpect(jsonPath("$.shortUrl").value(org.hamcrest.Matchers.endsWith("/" + code)))
                .andExpect(jsonPath("$.clickCount").value(0));
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(0));
        mockMvc.perform(get("/api/links/ZZZZZZZ"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail").isNotEmpty());
    }

    @Test
    void followRedirectsAndAccumulatesClicks() throws Exception {
        String url = "https://example.com/follow";
        String code = createAndReadCode(url);

        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", url));
        mockMvc.perform(get("/api/links/{code}", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(2));
    }

    @Test
    void unknownRedirectReturnsNotFound() throws Exception {
        mockMvc.perform(get("/ZZZZZZZ"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail").isNotEmpty());
    }

    @Test
    void concurrentFollowsPreserveEveryClick() throws Exception {
        String code = createAndReadCode("https://example.com/concurrent");
        int follows = 8;
        ExecutorService executor = Executors.newFixedThreadPool(follows);
        try {
            List<Future<MvcResult>> results = new ArrayList<>();
            for (int i = 0; i < follows; i++) {
